UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Несладкие радужные кексы (2 года+)'), description_ru = COALESCE(description_ru, 'Несладкие кексы с овощами и сыром, которые выглядят как настоящее лакомство.

Польза: Практичный способ помочь ребёнку, который привередлив в еде, полюбить разные овощи (разноцветный перец, зелень). Их также удобно брать с собой на прогулку в парк.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Яйца: 2 штуки","Йогурт: 2 столовые ложки","Оливковое масло: 1 столовая ложка","Красный перец и шпинат: очень мелко нарезанные (1-2 столовые ложки)","Сыр (тёртый): 2 столовые ложки","Мука и разрыхлитель (до консистенции густого теста для кексов)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Взбейте жидкие ингредиенты (яйца, йогурт, масло). Добавьте овощи и сыр.","В конце добавьте муку и разрыхлитель и перемешайте.","Разлейте тесто по формочкам для маффинов (кексов) и выпекайте при 180 градусах в течение 20 минут, пока кексы не поднимутся и не подрумянятся."]'::jsonb) WHERE id = '03922c9b-57cd-4e60-9084-3b45e0d48642';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тост с авокадо и чиа'), description_ru = COALESCE(description_ru, 'Более сытная и хрустящая версия классического тоста с авокадо, богатая Омега-3.

Польза: Сочетание семян чиа и авокадо — превосходный источник полезных жиров, которые помогают увлажнять кожу изнутри.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Чёрный или цельнозерновой хлеб: 1 ломтик (поджаренный)","Авокадо: половина (спелого)","Семена чиа: 1 чайная ложка","Лимонный сок, морская соль, хлопья красного перца."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разомните авокадо вилкой и смешайте с лимонным соком и солью. Щедро намажьте смесь на поджаренный хлеб. Сверху посыпьте семенами чиа и хлопьями красного перца, чтобы добавить хрустящую нотку и сделать тост ещё полезнее."]'::jsonb) WHERE id = '87d23e0f-a0db-4aa1-b0fb-794cb2b35b28';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Rose & Berry Spritz'), description_ru = COALESCE(description_ru, 'Жидкий коллаген и антиоксидантная поддержка для вашей кожи. Очень нежный и освежающий напиток.

Польза: Ягоды замедляют старение клеток, а розовая вода увлажняет кожу изнутри и придаёт ей естественный «glow» (сияние).'), category_ru = COALESCE(category_ru, 'Полезные напитки'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Свежая малина или клубника: 1 горсть","Розовая вода (питьевая, без добавок): 1 столовая ложка","Газированная вода (минеральная вода): 1 стакан","Лайм: 1 ломтик","Кубики льда."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Разомните ягоды вилкой на дне стакана. Добавьте лёд, розовую воду и сок лайма. В конце влейте газированную воду и перемешайте"]'::jsonb) WHERE id = 'f84c1bc3-0bf2-4206-b695-21d5ec9708da';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Десерт с куркумой'), description_ru = COALESCE(description_ru, 'Итальянская классика с противовоспалительными свойствами, придающая коже сияние.

Польза: Куркума и кокосовое молоко помогают бороться с акне изнутри, а желатин служит натуральным источником коллагена, укрепляющего ногти и волосы.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Кокосовое молоко (густое, консервированное): 1 стакан","Порошок куркумы: 1 чайная ложка","Мёд: 2 столовые ложки","Листовой желатин: 2 штуки (или 1 чайная ложка агар-агара)"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Замочите желатин в холодной воде. Нагрейте молоко в кастрюле (не доводите до кипения), добавьте куркуму, мёд и размягчённый желатин, затем перемешайте. Разлейте по небольшим стеклянным формочкам и оставьте застывать в холодильнике на 3-4 часа."]'::jsonb) WHERE id = '792abbe5-dddc-4848-8d97-bdcb84318aee';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Розовые блинчики «Фламинго» (3 года+)'), description_ru = COALESCE(description_ru, 'Завтрак с натуральным розовым цветом, который очарует детей, — и никаких пищевых красителей.

Польза: Свёкла улучшает кровообращение и поддерживает иммунитет. Овёс надолго сохраняет чувство сытости и заряжает ребёнка энергией.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Свекольное пюре: 1 столовая ложка (из варёной свёклы)","Яйцо: 1 штука","Овсяная мука: 3 столовые ложки","Молоко: Половина чайного стакана","Мёд: Совсем немного (для сладости)"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Смешайте все ингредиенты в блендере до получения совершенно однородного розового теста. Сформируйте небольшие кружочки и обжарьте с обеих сторон на сухой сковороде."]'::jsonb) WHERE id = '3c637a80-dd91-4c2f-bf85-45f21dbc4610';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Энергетические шарики «Метеориты» (5 лет+)'), description_ru = COALESCE(description_ru, 'Удобная несладкая «шоколадная» закуска, которую можно взять с собой в детский сад или парк.

Польза: Финики и какао быстро заряжают энергией, а грецкие или лесные орехи питают кожу и волосы жирными кислотами Омега-3.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Мягкие финики: 8-10 штук (без косточек)","Овсяные хлопья: Половина стакана","Какао (без сахара): 1 столовая ложка","Фундук или семена подсолнечника: 2 столовые ложки."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Измельчите все ингредиенты в блендере до получения липкой массы. Руками сформируйте небольшие «метеориты». При желании посыпьте их кокосовой стружкой. Перед подачей оставьте в холодильнике на 30 минут."]'::jsonb) WHERE id = '13882a92-abb0-49d4-b8c0-e8f4f9c2ea1b';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Пудинг с семенами льна и чиа'), description_ru = COALESCE(description_ru, 'Сытный и полезный для пищеварения пудинг, который готовится за 2 минуты и прекрасно подходит для завтрака или перекуса.

Польза: Семена чиа и льна впитывают воду в количестве, многократно превышающем их собственный вес, набухают, создают чувство сытости в желудке и помогают регулировать уровень сахара в крови.'), category_ru = COALESCE(category_ru, 'general'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Семена чиа: 2 столовые ложки","Семена льна (молотые): 1 столовая ложка","Миндальное молоко (или кокосовое молоко): 1 стакан","Натуральный экстракт ванили и 1 чайная ложка мёда."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Тщательно смешайте все ингредиенты в банке. Через 10 минут перемешайте ещё раз, чтобы не образовались комочки, и поставьте в холодильник (минимум на 2 часа или на всю ночь). Перед подачей украсьте фруктами."]'::jsonb) WHERE id = '9a57e53c-6cc6-4002-bebc-5ba8dd87a146';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Трюфели с матчей и фисташками'), description_ru = COALESCE(description_ru, '«Премиальное» дополнение к кофе, которое ускоряет метаболизм и помогает сохранить молодость кожи.

Польза: Чай матча — мощный антиоксидант, способствующий обновлению клеток. Кешью и фисташки питают и увлажняют кожу благодаря полезным жирам.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Кешью (сырой, замоченный): 1 стакан","Финики: 5-6 штук","Порошок матча: 1 столовая ложка (и дополнительно для обваливания)","Фисташки: Половина стакана (измельчённые)"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Измельчите все ингредиенты (кроме половины фисташек) в блендере до получения липкого теста. Руками сформируйте шарики, половину обваляйте в порошке матча, а другую половину — в измельчённых фисташках."]'::jsonb) WHERE id = 'ceb5db8c-58a7-4fde-a771-d2ed012eb9df';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Марокканский овощной тажин'), description_ru = COALESCE(description_ru, 'Североафриканское блюдо, которое медленно готовят в специальной посуде, сочетая сладкие и солёные вкусы овощей и фруктов.

Польза: Нут и овощи содержат сложные углеводы, помогающие регулировать уровень сахара в крови. Сухофрукты придают блюду естественную сладость без добавления сахара.'), category_ru = COALESCE(category_ru, 'general'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Нут (варёный): 1 стакан","Морковь, кабачок, батат (крупно нарезанные).","Курага или изюм: Половина стакана","Корица, зира (кумин), молотый имбирь, оливковое масло, овощной бульон."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["В глубокой кастрюле (или традиционной посуде для тажина) прогрейте специи в масле. Добавьте овощи, нут и сухофрукты. Залейте бульоном, накройте крышкой и готовьте на слабом огне до полной мягкости овощей (40-45 минут). Подавайте с киноа или кускусом."]'::jsonb) WHERE id = '71967587-de0b-4a79-8b91-69af7cbe3013';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Смузи-боул (4 года+)'), description_ru = COALESCE(description_ru, 'Весёлый десерт, который едят ложкой и который помогает полюбить овощи и фрукты в виде смузи.

Польза: Это настоящая витаминная бомба для поддержки иммунитета. Прекрасно подходит ребёнку для дневного перекуса.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Шпинат: 1 горсть","Замороженный банан: 1 штука","Киви: 1 штука","Йогурт или молоко: Половина стакана","Для украшения: Вырезанные из ломтиков киви «шипы» или кости динозавра."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Взбейте шпинат, банан, киви и молоко в блендере до консистенции густого крема. Перелейте в миску и украсьте ломтиками киви, чтобы они напоминали спину динозавра."]'::jsonb) WHERE id = '989c089a-7705-4f4f-aa06-64d202a23310';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Солнце Тосканы'), description_ru = COALESCE(description_ru, 'Лёгкая и полезная версия знаменитого итальянского блюда «Melanzane alla Parmigiana», приготовленная без обжаривания.

Польза: Баклажаны богаты антиоксидантами. Благодаря запеканию вместо традиционного обжаривания блюдо содержит намного меньше калорий, а белок из итальянских сыров делает его сытным.'), category_ru = COALESCE(category_ru, 'general'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Баклажаны: 2 крупных штуки (нарезанные вдоль)","Натуральная томатная паста: 2 стакана (приправленная чесноком и базиликом)","Сыры моцарелла и пармезан: Тёртые","Свежий базилик, оливковое масло."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Смажьте ломтики баклажанов оливковым маслом и запекайте в духовке до мягкости (15 минут). В глубокой форме для запекания выложите слоями, как лазанью: томатный соус, баклажаны, сыр и базилик. Верхним слоем должен быть сыр. Запекайте при 190 градусах 20 минут, пока сыр не подрумянится."]'::jsonb) WHERE id = '9e271ac6-efc7-4123-9cc8-b60e93936503';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Йогуртовая плитка с гранатом'), description_ru = COALESCE(description_ru, 'Яркая альтернатива мороженому. Прохладная и одновременно хрустящая.

Польза: Зёрна граната богаты фитоэстрогенами и антиоксидантами, которые помогают поддерживать баланс эстрогенов у женщин. А йогурт содержит пробиотики.'), category_ru = COALESCE(category_ru, 'Полезные сладости'), ingredients_ru = COALESCE(ingredients_ru, '["Йогурт (греческий или процеженный): 1.5 стакана","Мёд: 1 столовая ложка","Зёрна граната: Половина стакана","Фисташки: 2 столовые ложки (измельчённые)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Смешайте йогурт с мёдом и распределите слоем толщиной 0.5 см по плоской форме, застеленной пергаментной бумагой. Посыпьте гранатовыми зёрнами и фисташками, затем поставьте в морозильную камеру на 3 часа. После замораживания разломайте руками на кусочки, как плитку шоколада."]'::jsonb) WHERE id = '80d2e83c-c415-4e59-854e-3c904d65b0ff';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Белковая тарелка с курицей и киноа
(9 месяцев+)'), description_ru = COALESCE(description_ru, 'Источник длительной энергии для малышей, которые стали активнее и начали ползать.

Польза: курица — источник чистого белка, а киноа — безглютеновый суперфуд с самой высокой пищевой ценностью среди зерновых.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Куриная грудка: 30 qr","Цукини (кабачок): меньше половины","Киноа: 1 столовая ложка (предварительно замоченная и промытая)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Отварите курицу (первую воду слейте). Во вторую воду добавьте киноа и нарезанный цукини и варите до полной мягкости всех ингредиентов. Затем измельчите блендером или разомните вилкой, оставляя небольшие кусочки."]'::jsonb) WHERE id = '45628e71-5b41-431f-b26f-8283c2b308a2';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Хрустящие рыбные палочки (2 года+)'), description_ru = COALESCE(description_ru, 'Необжаренная и 100% натуральная версия замороженных рыбных палочек из магазина.

Польза: рыба содержит жирные кислоты Омега-3, необходимые для развития мозга и зрения малыша.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Филе белой рыбы (например, сибаса, без костей): 100 qr (нарезанное длинными полосками)","Яйцо: 1 штука (взбитое)","Овсяная мука (для панировки)","Оливковое масло, немного соли."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Сначала обмакните кусочки рыбы в яйцо, затем обваляйте в овсяной муке.","Выложите на противень, застеленный бумагой для выпечки, и слегка смажьте сверху оливковым маслом.","Запекайте при 190 градусах 15 минут до хрустящей корочки."]'::jsonb) WHERE id = 'cf74a166-77b4-4cd9-978f-5f84fbaf4d6d';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Кесадилья Супермена (5 лет+)'), description_ru = COALESCE(description_ru, 'Мексиканское блюдо со спрятанными внутри овощами, которое дети любят есть руками.

Польза: чёрная фасоль и курица — источники чистого белка, а сыр богат кальцием, укрепляющим кости.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Лаваш из цельнозерновой муки (тортилья): 1 штука","Голландский сыр (натёртый): 2 столовые ложки","Чёрная фасоль (варёная) и кукуруза: 1 столовая ложка","Куриное мясо, разобранное на волокна: 1 столовая ложка","Шпинат (очень мелко нарезанный): несколько листьев."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Выложите сыр, курицу, фасоль, кукурузу и шпинат на одну половину лаваша. Накройте второй половиной, сложив лаваш в форме полумесяца. Обжарьте с обеих сторон на горячей сковороде, пока сыр не расплавится, а лаваш не станет хрустящим. Разрежьте на треугольники и подавайте."]'::jsonb) WHERE id = '495abf5b-aca7-4840-8cc2-c8a7f267da78';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Карри с бататом и чечевицей'), description_ru = COALESCE(description_ru, 'Классическое блюдо индийской кухни с противовоспалительными специями, подходящее для веганского и безглютенового рациона.

Польза: карри и куркума укрепляют иммунитет, а батат придаёт блюду естественную нежную сладость.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Батат (сладкий картофель): 1 крупная штука (нарезанная кубиками)","Красная чечевица: 1 стакан","Кокосовое молоко (густое, консервированное): 1 стакан","Порошок карри: 1 столовая ложка","Шпинат: 1 горсть."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Обжарьте лук, чеснок и порошок карри в масле. Добавьте батат, чечевицу, кокосовое молоко и 2 стакана воды. Варите на медленном огне до полной готовности овощей. Сняв с огня, добавьте шпинат и перемешайте."]'::jsonb) WHERE id = '405b0576-a236-4ed8-8698-3423fb1d2ff0';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тефтельки с овощами (1 год+)'), description_ru = COALESCE(description_ru, 'Мягкие тефтельки со «спрятанными» внутри овощами для детей, которые отказываются их есть.

Польза: красное мясо помогает восполнить потребность в железе, а спрятанные овощи обеспечивают организм клетчаткой и витаминами. Идеально подходят для того, чтобы ребёнок мог брать их руками и есть самостоятельно.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Нежирный говяжий фарш: 150 qr","Цукини и морковь: по четверти каждого (очень мелко натёртые и отжатые)","Лук: очень маленький кусочек (натёртый)","Оливковое масло."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Тщательно смешайте и вымесите все ингредиенты. Сформируйте небольшие тефтельки размером с грецкий орех. Запекайте в духовке на противне, застеленном бумагой для выпечки, при 180 градусах 20-25 минут, не пересушивая."]'::jsonb) WHERE id = '2369413b-697e-4e19-93a2-ff9c61cde8f7';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Овощные палочки фри (5 лет+)'), description_ru = COALESCE(description_ru, 'Разноцветные хрустящие овощные палочки, запечённые в духовке, — полезная замена картофелю фри.

Польза: морковь и батат богаты витамином А и бета-каротином, которые поддерживают здоровье глаз и кожи.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Батат, морковь, цукини: по половине каждого","Оливковое масло: 1 столовая ложка","Сушёная мята или тимьян, немного соли."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Нарежьте овощи одинаковыми длинными палочками, похожими на волшебные. Смешайте с маслом и специями и разложите на противне в один слой. Запекайте при 200 градусах 20-25 минут, пока края не подрумянятся."]'::jsonb) WHERE id = 'a67b3fb0-1d8c-4568-bbb8-eea9c5b74c3a';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Золотой эликсир с матча'), description_ru = COALESCE(description_ru, 'Великолепный дуэт противовоспалительной куркумы и заряжающего энергией матча.'), category_ru = COALESCE(category_ru, 'Полезные напитки'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["1 чайная ложка матча, половина чайной ложки куркумы, щепотка чёрного перца, 1 стакан тёплого миндального молока, 1 чайная ложка мёда."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Добавьте все ингредиенты в тёплое молоко, тщательно перемешайте и взбейте до появления пены."]'::jsonb) WHERE id = '244e5027-cbdf-4e83-8b58-62158b64f304';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Цветная капуста в стиле «Баффало»'), description_ru = COALESCE(description_ru, '100% вегетарианская и полезная альтернатива популярному американскому блюду «Buffalo Wings» (куриным крылышкам).

Польза: полностью удовлетворяет желание съесть хрустящий фастфуд, но вместо курицы используется богатая клетчаткой цветная капуста, а вместо жарки — запекание в духовке.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Цветная капуста: 1 кочан (разделённый на соцветия)","Цельнозерновая мука и вода: для приготовления кляра (консистенции теста для блинов)","Острый соус «Баффало» (или смесь любого острого соуса со сливочным маслом)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Обмакните соцветия цветной капусты в смесь муки и воды и выложите на противень. Запекайте при 200 градусах 20 минут. Достаньте, полейте острым соусом и снова поставьте в духовку на 10 минут, пока края не станут хрустящими."]'::jsonb) WHERE id = '287fe4e5-acde-487e-8549-304293001ae7';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Андалузский бриз — испанский гаспачо'), description_ru = COALESCE(description_ru, 'Освежающий холодный суп из сырых помидоров, который пришёл с юга Испании и готовится без варки. Он богат витаминами.

Польза: Настоящий «цветочно-овощной» детокс. Благодаря ликопину (помидоры) и витамину C (перец) помогает защищать кожу изнутри от вредного воздействия солнечных лучей.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Очень спелые красные помидоры: 4-5 шт.","Огурец: 1 шт. (охлаждённый)","Зелёный болгарский перец: Половина","Красный лук и чеснок (совсем немного)","Оливковое масло первого холодного отжима (2 столовые ложки) и яблочный уксус (1 столовая ложка)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Поместите все ингредиенты в блендер, добавьте оливковое масло, уксус и немного соли, затем измельчите до полностью однородной жидкой консистенции супа. Оставьте в холодильнике минимум на 2 часа, чтобы суп стал очень холодным."]'::jsonb) WHERE id = '0732d705-b1b2-4b26-b8dc-748f80e0f06a';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Золотистые макароны с сыром (2 года+)'), description_ru = COALESCE(description_ru, 'Полезная версия любимых детьми макарон с сыром, в которой спрятаны овощи.

Польза: Вместо классического мучного и жирного соуса его основу составляют тыква и морковь. Блюдо богато витамином A и кальцием.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Цельнозерновые макароны (в форме рожков или спиралек): 1 стакан","Тыква и морковь (отварные): По половине стакана","Молоко: Половина стакана","Сыр чеддер (Cheddar) или голландский сыр: 3 столовые ложки в натёртом виде"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Отварите макароны в воде до полной готовности и откиньте на дуршлаг.","Взбейте в блендере приготовленные тыкву, морковь и молоко до получения полностью однородного оранжевого крема (соуса).","Вылейте соус на горячую сковороду, добавьте натёртый сыр и растопите его. В конце добавьте макароны в соус и перемешайте."]'::jsonb) WHERE id = '6a513f71-83a0-47b7-94eb-0de33be5ff6d';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Суп «Звёздная ночь» (3 года+)'), description_ru = COALESCE(description_ru, 'Аппетитный суп на костном бульоне с плавающими в нём звёздочками — для детей, которые не любят супы.

Польза: Костный бульон содержит коллаген и кальций, помогает укреплять кости и поддерживает рост детей.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['baby_food']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Чистый костный или куриный бульон: 2 стакана","Детские макароны в форме звёздочек: 2 столовые ложки","Морковь: Половина (нарезанная очень маленькими звёздочками)","Петрушка: Совсем немного (для украшения)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Доведите бульон до кипения, добавьте макароны-звёздочки и морковь, нарезанную в форме звёздочек. Варите до полной мягкости макарон (примерно 8-10 минут)."]'::jsonb) WHERE id = '60680ede-d11d-4b46-a277-695525f7d111';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Matcha Strawberry Cloud'), description_ru = COALESCE(description_ru, 'Самый популярный напиток в социальных сетях. Настоящая антиоксидантная бомба, питающая кожу.'), category_ru = COALESCE(category_ru, 'Полезные напитки'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["1 чайная ложка порошка матча (растворённого в тёплой воде), 4-5 шт. свежей клубники (размятой до состояния пюре), 1 стакан миндального молока, лёд."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Выложите клубничное пюре на дно стакана, добавьте лёд и молоко. В самом конце медленно влейте растворённую зелёную матчу, чтобы цвета сохранились слоями (розовый снизу, зелёный сверху)."]'::jsonb) WHERE id = '40f5ac74-8479-42d8-bab7-5b56e15de9ae';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Миндальные панкейки с чиа-джемом'), description_ru = COALESCE(description_ru, 'Безглютеновая версия обычных панкейков без добавленного сахара — полезная альтернатива для здорового образа жизни.

Польза: Миндальная мука не вызывает резкого повышения уровня сахара в крови (имеет низкий гликемический индекс). А чиа-джем позволяет отказаться от сахара, содержащегося в джемах промышленного производства.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Миндальная мука: 1 стакан","Яйца: 2 шт.","Миндальное молоко: Четверть стакана","Для джема: 1 стакан замороженной малины и 2 столовые ложки семян чиа."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Нагрейте и разомните малину, добавьте семена чиа и оставьте остывать и загустевать. Отдельно взбейте миндальную муку, яйца и молоко, затем приготовьте на сковороде небольшие панкейки. Полейте их домашним чиа-джемом без добавленного сахара."]'::jsonb) WHERE id = '0d809ddc-e476-418c-9f34-67e7b608cf9f';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Перуанское севиче'), description_ru = COALESCE(description_ru, 'Освежающее и богатое белком блюдо латиноамериканской кухни, в котором рыба без термической обработки маринуется только в цитрусовой кислоте.

Польза: Никакого дополнительного жира и максимум чистого белка. Одно из любимых блюд тех, кто придерживается диеты.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Филе белой рыбы (очень свежее и без костей): 200 qr (нарезанное маленькими кубиками)","Сок лайма: Половина стакана (свежевыжатый)","Красный лук: Половина (тонко нарезанная полукольцами)","Свежая кинза, острый перец халапеньо (по желанию), соль."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Положите кубики сырой рыбы в стеклянную ёмкость, залейте соком лайма и немного посолите. Под действием сока рыба побелеет, словно после приготовления. Оставьте в холодильнике на 20-30 минут. Перед подачей добавьте лук и кинзу и перемешайте."]'::jsonb) WHERE id = '53cbba9d-f39f-4a00-950a-386243d164bd';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Скандинавский Smørrebrød'), description_ru = COALESCE(description_ru, 'Искусство открытых бутербродов на тёмном ржаном хлебе, пришедшее из Дании и Норвегии.

Польза: Ржаной хлеб содержит сложные углеводы и не вызывает резких скачков сахара в крови. А лосось — богатый источник омега-3, которую считают одним из секретов долголетия скандинавов.'), category_ru = COALESCE(category_ru, 'общее'), ingredients_ru = COALESCE(ingredients_ru, '["Тёмный зерновой ржаной хлеб: 1 большой ломтик","Сливочный сыр (лабне): 1 столовая ложка","Нарезанный или слабосолёный лосось (сёмга): 2-3 ломтика","Кольца красного лука, свежий укроп, ломтики редиса."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Намажьте хлеб сливочным сыром. Выложите ломтики рыбы волнами. Украсьте кольцами лука, тонко нарезанным редисом и большим количеством укропа, затем красиво подайте."]'::jsonb) WHERE id = 'dded217d-3179-4368-8e13-255ed13ea4cf';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Табуле с киноа (ливанская кухня)'), description_ru = COALESCE(description_ru, 'Знаменитый ближневосточный салат, в котором традиционный булгур заменён безглютеновой киноа с более высоким содержанием белка.

Польза: Лёгкое блюдо, богатое клетчаткой и витамином C благодаря большому количеству петрушки. Помогает регулировать уровень сахара в крови.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Киноа (приготовленная и охлаждённая): 1 стакан","Свежая петрушка (очень мелко нарезанная): 2 больших пучка","Свежая мята: 1 маленький пучок","Помидоры: 2 шт. (нарезанные маленькими кубиками)","Зелёный лук: 3-4 пера","Оливковое масло первого холодного отжима, много лимонного сока и соль."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["В глубокой миске смешайте всю нарезанную зелень и овощи с приготовленной киноа. Щедро полейте оливковым маслом и лимонным соком, затем тщательно перемешайте. Оставьте в холодильнике минимум на 30 минут."]'::jsonb) WHERE id = '23f9812f-031f-4161-95cf-ce2d96da0985';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Спагетти из кабачков с соусом песто'), description_ru = COALESCE(description_ru, 'Чудесная паста, которая дарит удовольствие от мучного блюда, но совсем не способствует набору веса.

Польза: Очень низкокалорийное блюдо. Оливковое масло и базилик в соусе песто обладают мощными антиоксидантными свойствами и помогают сохранять молодость клеток.'), category_ru = COALESCE(category_ru, 'обед'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Кабачки: 2 среднего размера (нарезанные специальным прибором в виде спагетти)","Соус песто: 2 столовые ложки (свежий базилик, оливковое масло, грецкие орехи, измельчённый чеснок)","Помидоры черри: 4-5 шт."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Слегка обжарьте спагетти из кабачков на сковороде с небольшим количеством оливкового масла всего 2-3 минуты (не передерживайте, чтобы они остались хрустящими). Снимите с огня и смешайте с соусом песто и разрезанными пополам помидорами."]'::jsonb) WHERE id = '4562e352-5778-4e1f-951e-cc27bf63469a';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Соте из брокколи и говядины'), description_ru = COALESCE(description_ru, 'Одно из самых полезных классических блюд знаменитой азиатской (китайской) кухни, любимое во всём мире.

Польза: Создаёт прекрасный баланс железа (из мяса), кальция и витамина C (из брокколи). Быстро готовится.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Говядина (вырезка, нарезанная очень тонкими ломтиками): 250 гр","Брокколи: 1 целый кочан (разделённый на соцветия)","Соевый соус (с пониженным содержанием соли): 3 столовые ложки","Свежий имбирь и чеснок (измельчённые).","Кунжутное масло и семена кунжута."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Быстро обжарьте мясо в сковороде (вок) на сильном огне и отложите в сторону. В ту же сковороду добавьте брокколи, чеснок и имбирь и обжаривайте 3-4 минуты (брокколи должна остаться хрустящей). Верните мясо, добавьте соевый соус, перемешивайте 1 минуту, затем посыпьте кунжутом и снимите с огня."]'::jsonb) WHERE id = 'cdafe114-fffe-4d67-b795-0770d33715ea';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Крекеры из льняной и миндальной муки'), description_ru = COALESCE(description_ru, 'Домашние крекеры без углеводов (Кето) и на 100% без глютена, которые заменят вредные магазинные чипсы.

Польза: Миндальная мука богата витамином E, а семена льна прекрасно регулируют работу кишечника.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Миндальная мука: 1 стакан","Семена льна (молотые): 3 столовые ложки","Вода: 3 столовые ложки","Оливковое масло: 1 столовая ложка","Соль и сушёный тимьян."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Смешайте и вымесите все ингредиенты в миске до получения теста. Очень тонко раскатайте скалкой между двумя листами бумаги для выпечки — как чипсы. Нарежьте ножом на квадраты и выпекайте в духовке при 170 градусах 15-20 минут до хрустящей корочки."]'::jsonb) WHERE id = 'd73926c7-3c66-41bd-88a6-1a28c3a2f959';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Магия какао и маки'), description_ru = COALESCE(description_ru, 'Тёплый вкусный напиток, который помогает сбалансировать женские гормоны и повышает уровень гормона счастья.

Польза: Порошок корня «Maca» (мака) родом из Перу помогает регулировать гормональный фон у женщин (в период ПМС и менопаузы), повышает энергию и либидо. Какао является источником магния.'), category_ru = COALESCE(category_ru, 'Полезные напитки'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Чистый какао-порошок без сахара: 1 столовая ложка","Порошок Maca (мака): 1 чайная ложка","Миндальное или фундучное молоко: 1 стакан","Корица и мёд."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Подогрейте все ингредиенты в небольшой кастрюле, тщательно взбивая до появления пены. Пейте как горячий шоколад, чтобы побаловать себя во второй половине дня."]'::jsonb) WHERE id = '9af7ce60-d92c-4cdf-bbaf-e2276dc4e407';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Блонди из нута'), description_ru = COALESCE(description_ru, 'Карамельный кекс без муки, в котором никто не догадается о присутствии нута.

Польза: Этот десерт содержит полноценный белок и сложные углеводы. Он не вызывает вздутия из-за глютена и прекрасно сочетается с чаем после вечерней тренировки (для восстановления мышц).'), category_ru = COALESCE(category_ru, 'Полезные десерты'), tags_ru = COALESCE(tags_ru, ARRAY['general']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Консервированный нут: 1 стакан (тщательно промытый и очищенный от кожицы)","Арахисовая паста: 3 столовые ложки","Мёд или кленовый сироп: 3 столовые ложки","Ваниль, разрыхлитель.","Шоколадные капли (тёмные)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Измельчите в блендере все ингредиенты, кроме шоколада, до получения полностью однородной массы (теста). Добавьте шоколадные капли, перемешайте и вылейте в небольшую квадратную форму для кекса. Выпекайте при 175 градусах 20 мин. Нарежьте, пока кекс ещё тёплый."]'::jsonb) WHERE id = '4b5bc08b-15b1-4187-aa19-05b7b3bb4ae4';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Индийское пюре из чечевицы'), description_ru = COALESCE(description_ru, 'Любимое блюдо вегетарианцев — золотистое индийское рагу, которое согревает изнутри благодаря силе пряностей.

Польза: куркума и имбирь помогают уменьшить воспаление в организме. А чечевица благодаря растительному белку надолго сохраняет чувство сытости.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Красная или жёлтая чечевица: 1 стакан","Лук, чеснок, свежий имбирь.","Куркума и порошок карри: по 1 чайной ложке.","Помидор: 1 штука","Кокосовое молоко: совсем немного (для подачи)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Обжарьте лук, чеснок, имбирь и специи в масле до появления аромата. Добавьте нарезанный помидор и чечевицу. Влейте воду и готовьте, пока чечевица полностью не разварится до консистенции пюре (рагу). Полейте кокосовым молоком и посыпьте кинзой."]'::jsonb) WHERE id = 'f1edbb7c-89ad-49b8-9c59-42461d445810';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Немецкий картофельный салат'), description_ru = COALESCE(description_ru, 'Великолепный лёгкий немецкий салат с горчицей и уксусом, который оставляет тяжёлые майонезные салаты далеко позади.

Польза: в охлаждённом картофеле образуется пребиотический «резистентный крахмал», полезный для кишечника. Отсутствие майонеза помогает избежать лишнего холестерина.'), category_ru = COALESCE(category_ru, 'общее'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Картофель: 3-4 штуки (отваренные, охлаждённые, нарезанные ломтиками)","Красный лук: 1 небольшая головка (мелко нарезанная)","Свежая петрушка или укроп","Для соуса: 1 столовая ложка зернистой горчицы, 2 столовые ложки яблочного уксуса, 3 столовые ложки оливкового масла, соль, чёрный перец."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Добавьте лук и зелень к тёплым или полностью остывшим ломтикам картофеля. Встряхните в банке горчицу, уксус и масло, чтобы приготовить соус, а затем перемешайте его с салатом."]'::jsonb) WHERE id = 'bfa226ee-4fae-4a95-b348-aee056cab96b';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Макароны с сыром от Шрека (3 года+)'), description_ru = COALESCE(description_ru, 'Сырные макароны со спрятанным внутри шпинатом, которые привлекают внимание красивым зелёным цветом.

Польза: многие дети в возрасте 3 лет отказываются есть шпинат в сыром или приготовленном виде. Благодаря этому соусу они получат много железа, даже не заметив шпинат.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Макароны: 1 стакан","Шпинат: 1 большая горсть","Молоко: половина стакана","Моцарелла или сыр гауда: 2 столовые ложки (натёртый)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Отварите макароны и слейте воду. Измельчите в блендере шпинат с молоком до получения однородной зелёной жидкости без комочков. Вылейте это зелёное молоко на горячую сковороду, добавьте сыр и растопите его. В конце добавьте макароны и тщательно перемешайте."]'::jsonb) WHERE id = '82a7ccbd-e708-435c-afe7-61fd5589966e';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Золотистый суп из чечевицы и имбиря'), description_ru = COALESCE(description_ru, 'Согревающий изнутри зимний обед, который активизирует обмен веществ.

Польза: имбирь и куркума помогают уменьшить проявления воспаления в организме (отёчность, акне, боли в суставах), а красная чечевица надолго сохраняет чувство сытости.'), category_ru = COALESCE(category_ru, 'обед'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Красная чечевица: 1 стакан","Свежий имбирь: размером с лесной орех (натёртый)","Куркума: половина чайной ложки","Морковь, лук.","Кокосовое молоко: 2 столовые ложки (по желанию, для подачи)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Отварите все овощи и чечевицу в воде до мягкости, затем измельчите блендером. Добавьте куркуму и имбирь и поварите ещё немного. При подаче полейте суп в тарелке кокосовым молоком."]'::jsonb) WHERE id = '9dca9acb-e3bc-495a-9af1-62c75bc63dca';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Батат с фасолью'), description_ru = COALESCE(description_ru, 'Рецепт, который помогает контролировать тягу к сладкому и перепады настроения во время ПМС (перед менструацией).

Польза: батат и чёрная фасоль богаты магнием, помогают успокоить нервную систему, уменьшить спазмы и надолго сохранить чувство сытости.'), category_ru = COALESCE(category_ru, 'обед'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Батат: 1 штука (разрезанный пополам и полностью запечённый в духовке)","Чёрная фасоль (или красная): 2 столовые ложки (отваренная)","Кукуруза: 1 столовая ложка","Пюре из авокадо (гуакамоле) и сок лайма."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Наполните середину запечённого и мягкого внутри батата чёрной фасолью и кукурузой. Сверху выложите пюре из авокадо и сбрызните соком лайма."]'::jsonb) WHERE id = '0298f702-76b2-4fe4-995b-506dab64f0f1';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Пюре «Медвежонок» (1 год+)'), description_ru = COALESCE(description_ru, 'Сочное зимнее блюдо, которое тает во рту и подходит детям, испытывающим трудности с пережёвыванием мяса.

Польза: мясо, приготовленное в течение длительного времени, легче переваривается, а бульон полезен для развития костей.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Говядина: 50 qr (очень мелкие кубики размером с горошину)","Морковь и картофель: по половине штуки (нарезанные кубиками)","Помидор: четверть (натёртая)","Оливковое масло и вода."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Обжарьте мясо в оливковом масле до изменения цвета, добавьте помидор и воду и готовьте до мягкости (лучше в скороварке). Затем добавьте морковь и картофель и готовьте, пока овощи не станут настолько мягкими, что их можно будет размять."]'::jsonb) WHERE id = 'a7eb16f8-9a88-4ac0-92d3-fb7d3da355e0';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Тоник «Золотое сияние»'), description_ru = COALESCE(description_ru, 'Утренний тоник, который помогает уменьшить воспаление в организме и укрепить защиту от болезней.

Польза: куркума обладает выраженными природными противовоспалительными свойствами. Она помогает уменьшить покраснение кожи и боли в суставах, а также вернуть коже естественное сияние.'), category_ru = COALESCE(category_ru, 'Полезные напитки'), tags_ru = COALESCE(tags_ru, ARRAY['общее']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Тёплая вода: 1 стакан","Порошок куркумы: половина чайной ложки","Чёрный перец: одна щепотка (необходим для усвоения куркумы)","Лимонный сок и 1 чайная ложка натурального яблочного уксуса"]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Тщательно смешайте все ингредиенты и пейте утром небольшими глотками в тёплом виде (напиток не должен обжигать горло и желудок)."]'::jsonb) WHERE id = '55d6317c-4bcb-4a93-943a-dda17af68226';
UPDATE public.admin_recipes SET title_ru = COALESCE(title_ru, 'Разноцветные шашлычки (5 лет+)'), description_ru = COALESCE(description_ru, 'Шашлычки, в которых овощи и мясо подаются вместе в виде яркой игры.

Польза: это самый практичный способ в игровой форме предложить детям одновременно и белок, и витамины.'), category_ru = COALESCE(category_ru, 'Прикорм'), tags_ru = COALESCE(tags_ru, ARRAY['детское_питание']::text[]), ingredients_ru = COALESCE(ingredients_ru, '["Куриная грудка: 100 qr (обжаренная или отваренная, нарезанная кубиками)","Разноцветный болгарский перец (красный, жёлтый), помидоры черри и огурец (нарезанные толстыми кусочками).","Деревянные палочки с тупыми концами (шпажки)."]'::jsonb), instructions_ru = COALESCE(instructions_ru, '["Поочерёдно нанижите на палочки: помидор черри, кубик курицы, жёлтый перец, огурец и снова курицу. Старайтесь располагать цвета как радугу."]'::jsonb) WHERE id = 'd945cba8-c55e-4693-91cb-3385f3ce8b99';

