UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Бег марафона'), description_ru = COALESCE(description_ru, 'Во время беременности бег на марафонские дистанции обычно не рекомендуется из-за высокой физической нагрузки и потенциальных рисков. Для получения индивидуальных рекомендаций проконсультируйтесь с врачом.') WHERE id = '2816eb9b-6c75-4242-869c-91b793782e84';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Микроблейдинг'), description_ru = COALESCE(description_ru, 'Не рекомендуется из-за риска инфекции и болевых ощущений.') WHERE id = '2841191c-cf23-4b01-bf5f-86a558ecb36a';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Йод'), description_ru = COALESCE(description_ru, 'Необходим для работы щитовидной железы и развития мозга плода.') WHERE id = '28775f4a-1fa8-4cb7-8dac-0132827acef9';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Абгора'), description_ru = COALESCE(description_ru, 'Безопасна (сок незрелого винограда).') WHERE id = '2a3c43e7-7984-4ed2-b2db-4df9dd48adbd';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кукуруза (Варёная)'), description_ru = COALESCE(description_ru, 'Это безопасный перекус.') WHERE id = '2ac2b30a-da50-4793-b7a3-857694634a38';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Лечение Зубов'), description_ru = COALESCE(description_ru, 'Местная анестезия (лидокаин) безопасна для беременных. Важно своевременно лечить инфекцию.') WHERE id = '2b2dad7b-3bcb-456f-8c6d-6200781cc993';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Ламинирование Бровей'), description_ru = COALESCE(description_ru, 'Химические вещества могут попасть на кожу. Сделайте тест на аллергию.') WHERE id = '2b3dc439-9ff4-4b53-993b-7cea853548d1';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Семечки (Подсолнечника)'), description_ru = COALESCE(description_ru, 'Являются источником фолиевой кислоты и витамина E.') WHERE id = '2ba4fe11-76b1-4110-8626-0826230bb91c';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Витамин D'), description_ru = COALESCE(description_ru, 'Следует принимать в дозировке, назначенной врачом.') WHERE id = '2c380853-1d73-4853-a94f-5df5664edb6d';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Хингал (листовой)'), description_ru = COALESCE(description_ru, 'Это блюдо из теста, оно безопасно. Мясной фарш должен быть полностью приготовлен.') WHERE id = '175f0053-64b2-4e76-b5a5-673b01d8ac1e';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кунжут'), description_ru = COALESCE(description_ru, 'Можно употреблять в небольшом количестве, например, на хлебе или в виде тахини. В больших дозах может воздействовать на матку.') WHERE id = '19ca769a-11f7-46db-8963-6172b215a50a';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Наращивание ресниц'), description_ru = COALESCE(description_ru, 'Безопасно, если у вас нет реакции на запах клея.') WHERE id = '19d422d5-be20-4643-8e69-e66fb97f5167';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Мытьё окон'), description_ru = COALESCE(description_ru, 'Существует риск падения с высоты. Будьте осторожны.') WHERE id = '19fe3138-0e8f-487a-88e9-ac466b8e7455';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Окрашивание волос'), description_ru = COALESCE(description_ru, 'Допустимо после 1-го триместра, в хорошо проветриваемом помещении и с использованием безаммиачных красок.') WHERE id = '1c5a11d7-6647-4d9c-b566-6ed1d207f677';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Шашлык (мясо)'), description_ru = COALESCE(description_ru, 'Мясо должно быть полностью приготовлено (не должно оставаться "с кровью"). Подгоревшие части есть не рекомендуется.') WHERE id = '1ec8f09a-93f7-4090-a7b3-291ec4bebda6';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Работа за компьютером'), description_ru = COALESCE(description_ru, 'Каждый час вставайте и немного ходите, чтобы улучшить кровообращение.') WHERE id = '214a8105-e97d-46f4-bfa3-4285b64abb38';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Зелёный чай'), description_ru = COALESCE(description_ru, 'Содержит кофеин и может препятствовать усвоению фолиевой кислоты. Не более 1 чашки в день.') WHERE id = '2480a0e0-51da-49e1-9ad2-f6accaaf2639';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Эфирные масла'), description_ru = COALESCE(description_ru, 'Избегайте их в первые 3 месяца. Позже можно использовать небольшое количество масла лаванды или чайного дерева.') WHERE id = '256b8c29-d4c6-497b-96ad-14febc117057';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Алоэ вера (гель)'), description_ru = COALESCE(description_ru, 'Наносить на кожу безопасно. Принимать внутрь (в виде сока) нельзя из-за слабительного действия.') WHERE id = '25c7527b-591c-4620-959d-e45daeaea7e8';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Чай из шиповника'), description_ru = COALESCE(description_ru, 'Богат витамином C, полезен при простуде.') WHERE id = '3f136261-51b1-4e72-b8ca-44853eff06b6';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Соленья (маринады)'), description_ru = COALESCE(description_ru, 'Безопасны и повышают аппетит. Из-за содержания соли могут вызывать отёки.') WHERE id = '3f8bf8fd-9d0c-44e6-bcfe-aba1fd9bdaba';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Анальгин'), description_ru = COALESCE(description_ru, 'Может негативно влиять на кроветворение. Выбирайте парацетамол.') WHERE id = '410cde1d-5aea-4d7b-bb9b-fe8f45a749d3';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Айран / Довга'), description_ru = COALESCE(description_ru, 'Безопасны, улучшают пищеварение.') WHERE id = '41b1cc04-5909-43be-8ce4-86fb1ead21b8';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Хлеб (цельнозерновой)'), description_ru = COALESCE(description_ru, 'Полезнее белого хлеба.') WHERE id = '438a265a-32b5-43b2-a441-d5edbb5699d7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Пустырник'), description_ru = COALESCE(description_ru, 'Используется как успокоительное средство, но проконсультируйтесь с врачом.') WHERE id = '43a45a81-8784-41a1-b75a-fb08a503e946';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кинза'), description_ru = COALESCE(description_ru, 'Безопасна в пищевых количествах (как зелень).') WHERE id = '4409ab79-8040-400f-874e-3014663cbb59';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Акриловые / гелевые ногти'), description_ru = COALESCE(description_ru, 'Надевайте маску для защиты от пыли и запаха химических веществ. УФ-лампа безопасна.') WHERE id = '445ab6ae-6f5b-45dd-948c-e1fb40b68b41';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Ромашковый чай'), description_ru = COALESCE(description_ru, 'Обладает успокаивающим действием, но в больших количествах может влиять на матку. Ограничьтесь 1 чашкой в день.') WHERE id = '455c2f5c-a585-4549-98c6-f4a465fe10e5';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Чёрная икра'), description_ru = COALESCE(description_ru, 'Если она пастеризована, то является источником белка и омега-3.') WHERE id = '4736feb8-a7c7-47ab-83f0-c0063f1903f5';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Безалкогольное пиво'), description_ru = COALESCE(description_ru, 'Может содержать незначительное количество (0.5%) алкоголя. Будьте осторожны.') WHERE id = '3473200c-9a7d-48b0-928c-8e9da88800b1';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Бадамбура'), description_ru = COALESCE(description_ru, 'Безопасно.') WHERE id = '35464939-dd9e-4116-b32a-0eae5ac720f8';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Пребывание на солнце'), description_ru = COALESCE(description_ru, 'Умеренное пребывание на солнце, как правило, безопасно и способствует выработке витамина D. Однако длительное воздействие солнца может привести к обезвоживанию, тепловому удару и солнечным ожогам, которые вызывают дискомфорт и могут быть опасны. Рекомендуется ограничивать пребывание под прямыми солнечными лучами, особенно в часы пиковой солнечной активности (с 10 утра до 4 вечера), носить защитную одежду, использовать солнцезащитный крем и пить больше жидкости.') WHERE id = '3982c1ae-13f7-4142-8726-4f0481aa7c58';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Баклажан'), description_ru = COALESCE(description_ru, 'Безопасен и полезен.') WHERE id = '3c93069d-d293-4b0f-ad5e-34bac1fe54c6';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Плавание'), description_ru = COALESCE(description_ru, 'Один из лучших видов физической активности. Отдавайте предпочтение бассейну с чистой водой или морю.') WHERE id = '3cea4532-7848-493f-a0d6-e06099618ef1';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Ретинол (витамин A)'), description_ru = COALESCE(description_ru, 'Запрещён в составе кремов и таблеток. Может оказывать тератогенное воздействие на плод.') WHERE id = '3d080cee-a173-4d17-8b0b-c3313c09349e';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Солярий'), description_ru = COALESCE(description_ru, 'Перегрев и УФ-лучи вредны. Кремы-автозагары (Self-tan) безопаснее.') WHERE id = '3d4abaa1-3e7a-4a70-ba17-3a98380b262e';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Цветная капуста'), description_ru = COALESCE(description_ru, 'Является источником фолиевой кислоты.') WHERE id = '3dcd690d-13ac-4649-adb0-5f3754e504df';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Общественная баня'), description_ru = COALESCE(description_ru, 'Не рекомендуется из-за риска инфекций и воздействия высокой температуры.') WHERE id = '3e56c556-b839-4f2c-b232-3ab20776411e';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кутаб (с зеленью/мясом)'), description_ru = COALESCE(description_ru, 'Зелень необходимо тщательно вымыть, а мясо — полностью приготовить.') WHERE id = '3ee1c3b7-b903-492c-8602-996750c186b8';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Бургер (фастфуд)'), description_ru = COALESCE(description_ru, 'Мясо должно быть полностью прожарено. Чистота салата может вызывать сомнения.') WHERE id = '48610fa7-1910-457d-9078-9733a4ac93ef';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Натуральные соки'), description_ru = COALESCE(description_ru, 'Пастеризованные соки безопасны. Свежевыжатые соки следует пить сразу после приготовления.') WHERE id = '48e91094-2376-4f8b-9fcb-b8dff5dabdd6';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Пити'), description_ru = COALESCE(description_ru, 'Содержит много жира (курдючного), поэтому может затруднять пищеварение.') WHERE id = '4afbfd15-403c-4f25-8b02-aa586d685816';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Средство от насекомых'), description_ru = COALESCE(description_ru, 'Токсично. Во время обработки дома от насекомых находитесь на улице.') WHERE id = '4bb29538-26fa-451d-93c6-87de4551a116';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Драконий фрукт'), description_ru = COALESCE(description_ru, 'Драконий фрукт в целом безопасен для употребления во время беременности. Это хороший источник витаминов, минералов и клетчатки, которые могут быть полезны беременным женщинам.') WHERE id = '4bc02c92-bff2-4d26-b42d-9123d3f84aed';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Квас'), description_ru = COALESCE(description_ru, 'Может содержать небольшое количество алкоголя (продукт брожения). Будьте осторожны.') WHERE id = '4bf58079-aa14-4344-8177-0c7e093fb7fd';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Хна'), description_ru = COALESCE(description_ru, 'Натуральная хна безопасна. Избегайте «чёрной хны» с химическими добавками.') WHERE id = '4d71f90e-d40d-49a3-a894-6e5ac5b95bc2';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Дыня'), description_ru = COALESCE(description_ru, 'Безопасна, но её необходимо тщательно мыть из-за возможных бактерий на кожуре.') WHERE id = '4e56afe8-e5aa-4f52-9505-f2461311be94';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Димедрол'), description_ru = COALESCE(description_ru, 'Может вызвать сокращения матки, поэтому не рекомендуется.') WHERE id = '4e861e2a-5668-4dd0-b2c7-733c3191cebf';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Назальные спреи'), description_ru = COALESCE(description_ru, 'Солевой раствор (Аквамарис) полностью безопасен. Сосудосуживающие средства (Ксилометазолин) можно применять не дольше 3-5 дней.') WHERE id = '4ed749d3-e969-49f1-95f3-cb9354d1022c';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Железо (Iron)'), description_ru = COALESCE(description_ru, 'При анемии — только по назначению врача. Может вызвать запор.') WHERE id = '56778e31-ace8-48db-ae70-70dece506207';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Сухофрукты'), description_ru = COALESCE(description_ru, 'Изюм, курага и сушёные абрикосы безопасны (их следует тщательно мыть).') WHERE id = '56815cf3-8027-47e0-98e6-8d6cdd30d7f7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Горчица'), description_ru = COALESCE(description_ru, 'В небольшом количестве в качестве соуса безопасна.') WHERE id = '56b28fa6-2463-4319-a977-abdfc415b72f';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Прыжки (Jumping)'), description_ru = COALESCE(description_ru, 'Из-за повышенной подвижности суставов существует риск травм. Оказывают давление на матку.') WHERE id = '580c9e78-3ae2-44f8-a423-d1a876ee79a7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Розовая вода'), description_ru = COALESCE(description_ru, 'Безопасна, обладает успокаивающим действием.') WHERE id = '583251f4-b8d0-49fb-94d8-09b5b5b8dd82';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Помидор'), description_ru = COALESCE(description_ru, 'Безопасен, является источником ликопина.') WHERE id = '594fcc68-fc42-4bca-900f-141656343888';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Фаршированные баклажаны'), description_ru = COALESCE(description_ru, 'Безопасны (летняя долма).') WHERE id = '5982e012-62cf-416e-b576-902b951f4204';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Пассивное курение'), description_ru = COALESCE(description_ru, 'Находиться в задымлённом помещении также вредно.') WHERE id = '59e013bf-1a25-4372-bb1b-e6c0f3f5d350';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кокосовое масло'), description_ru = COALESCE(description_ru, 'Безопасно.') WHERE id = '59fb3680-4faa-49c9-94f4-50c108fe46e7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Домашние животные (собака)'), description_ru = COALESCE(description_ru, 'Безопасно. Не позволяйте собаке прыгать вам на живот.') WHERE id = '5a458d09-50b8-41b9-bd96-a563718fc867';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Комбуча'), description_ru = COALESCE(description_ru, 'Может содержать небольшое количество алкоголя и живые бактерии.') WHERE id = '4f691cd1-d199-495e-ad77-36cafbbe20a5';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Красная икра'), description_ru = COALESCE(description_ru, 'Безопасна, если пастеризована.') WHERE id = '4ff28cff-1e5f-4c00-9bf5-da800caafa84';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Концерт'), description_ru = COALESCE(description_ru, 'Очень громкий звук может беспокоить малыша.') WHERE id = '50fbfc91-971a-4630-9616-e61d1e952266';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Маргарин'), description_ru = COALESCE(description_ru, 'Содержит трансжиры, поэтому лучше отдавать предпочтение сливочному маслу.') WHERE id = '519f485f-bbfa-43a2-ab16-3cf1e139361b';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Сырое молоко'), description_ru = COALESCE(description_ru, 'Непрокипячённое фермерское молоко может быть источником бактерий. Его необходимо обязательно кипятить или покупать пастеризованным.') WHERE id = '5244c1bd-462f-4e11-80c4-c7698bf4eb81';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кюкю'), description_ru = COALESCE(description_ru, 'Безопасно, если зелень и яйца полностью приготовлены.') WHERE id = '529cbeb0-75e5-405b-980d-b468a119e536';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Мороженое'), description_ru = COALESCE(description_ru, 'Безопасно, если приготовлено из пастеризованного молока. Мягкое мороженое, продаваемое на улице, может быть связано с риском бактериального заражения.') WHERE id = '5340f447-5183-44c1-a1e3-6279a989c56c';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Ремонт (запах краски)'), description_ru = COALESCE(description_ru, 'Пары растворителей и красок вредны. Не оставайтесь в помещении.') WHERE id = '53bfc9ec-dd79-4134-9377-7aa0dbecaa42';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Майонез'), description_ru = COALESCE(description_ru, 'Домашний майонез с сырыми яйцами употреблять нельзя. Магазинный майонез с пастеризованными яйцами безопасен.') WHERE id = '55091d3f-e65c-41cc-91a3-9aee86cea4b1';
