UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Бег (Running)'), description_ru = COALESCE(description_ru, 'Если вы бегали до беременности, можете продолжать в спокойном темпе. Начинать бегать во время беременности не следует.') WHERE id = '92962cf9-e5ec-49cb-81b4-c102843ffd96';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Папаверин (свечи)'), description_ru = COALESCE(description_ru, 'Применяется при повышенном тонусе матки. Только по назначению врача.') WHERE id = '92a311a8-2353-49f2-a478-69bbb6e11521';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Но-шпа (Дротаверин)'), description_ru = COALESCE(description_ru, 'В Азербайджане часто назначается при повышенном тонусе матки. Применяйте только после консультации с врачом.') WHERE id = '92a61566-5cda-42e3-aa3b-f9e0870a058d';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Зелёнка (Бриллиантовый зелёный)'), description_ru = COALESCE(description_ru, 'Безопасна при наружном применении (для обработки ран).') WHERE id = '92d5127f-93c5-475a-8efe-d203d95f8692';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Компрессионные чулки'), description_ru = COALESCE(description_ru, 'Помогают предотвратить варикоз и уменьшить отёки.') WHERE id = '936379c9-7b34-4707-87a4-0cb406f01a7e';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Ананас'), description_ru = COALESCE(description_ru, 'Миф: чтобы спровоцировать роды, нужно съесть 7-8 целых ананасов. В умеренном количестве безопасен.') WHERE id = '9465bd4b-eaf1-49d5-b708-d311399b2d80';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Донер'), description_ru = COALESCE(description_ru, 'Может представлять гигиенический риск. Покупайте его только в проверенном месте и убедитесь, что мясо полностью приготовлено.') WHERE id = '94bf5000-5697-4c9b-b884-b1e8c0efbcda';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Гибискус (Каркаде)'), description_ru = COALESCE(description_ru, 'Некоторые исследования указывают на возможное влияние на гормональный фон, поэтому рекомендуется воздержаться.') WHERE id = '94c2c047-2843-4200-936a-3a9fc44240f1';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Танцы'), description_ru = COALESCE(description_ru, 'Поднимают настроение. Избегайте резких движений и прыжков.') WHERE id = '9680b85e-c13d-4194-be28-5232a7f113b1';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Сушка волос феном'), description_ru = COALESCE(description_ru, 'Безопасна.') WHERE id = '9811160d-50b0-49ee-ad9a-de2887d861ff';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Мягкие сыры'), description_ru = COALESCE(description_ru, 'Непастеризованные (деревенские) сыры, бри, камамбер и горгонзола (сыры с плесенью) несут риск заражения листерией.') WHERE id = 'a7b8c93a-6b20-42cb-a6bb-3c24c2d463dd';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Энергетические напитки'), description_ru = COALESCE(description_ru, 'Запрещены из-за высокого содержания кофеина, таурина и химических добавок.') WHERE id = 'a90e3ed7-29b4-4069-9da6-756cd3c34d3b';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Автозагар (спрей)'), description_ru = COALESCE(description_ru, 'Остаётся на поверхности кожи и не проникает в кровь. Но старайтесь не вдыхать спрей.') WHERE id = 'a92ffa8d-a22e-42a9-b273-e99051d02431';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Гогал'), description_ru = COALESCE(description_ru, 'Из-за пряностей может вызвать изжогу.') WHERE id = 'a935f993-7f7f-48c5-86da-aa2d5e8367c7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Пилатес'), description_ru = COALESCE(description_ru, 'Укрепляет мышцы поясницы. Инструктор должен знать о вашей беременности.') WHERE id = 'a9929822-3bb0-4d7c-a4c2-2a4b33e92a3e';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Хаш / Келле-пача'), description_ru = COALESCE(description_ru, 'Это очень жирные блюда, которые могут повысить уровень холестерина. Чеснок может вызвать дискомфорт в желудке.') WHERE id = 'aacd53cb-1bb0-4268-a1d1-9f9c135ab7ce';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Острый перец'), description_ru = COALESCE(description_ru, 'Безопасен, но может усилить изжогу.') WHERE id = 'ab3fa79f-82f8-4fc2-a110-8c6d47485087';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Антигистаминные препараты (от аллергии)'), description_ru = COALESCE(description_ru, 'Проконсультируйтесь с врачом. Лоратадин и цетиризин обычно считаются безопасными.') WHERE id = 'abf9d1a9-234a-433d-9ccb-84b093abd005';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Горячая ванна / сауна'), description_ru = COALESCE(description_ru, 'Повышение температуры тела выше 39°C опасно для плода. Можно принимать тёплый душ.') WHERE id = 'ac0aee5f-a79c-4c84-b5d8-ef03a487b436';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Садж-ичи'), description_ru = COALESCE(description_ru, 'Блюдо может быть очень жирным и сильно обжаренным. Овощная часть более полезна.') WHERE id = 'acb890db-b750-4b72-8f5e-e8344e92d7a5';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Шугаринг / Восковая эпиляция'), description_ru = COALESCE(description_ru, 'Безопасны при отсутствии расширения вен (варикоза). Кожа может стать более чувствительной.') WHERE id = '99c14318-3cfc-4075-b0a9-fe0b308313db';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Малина / Ежевика'), description_ru = COALESCE(description_ru, 'В свежем виде безопасны. Не путайте с чаем из листьев.') WHERE id = '9a1a747c-7173-43b6-9b93-c2a5d9023c83';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Творог (пастеризованный)'), description_ru = COALESCE(description_ru, 'Магазинный творог безопасен и является источником кальция. Сырой творог, продаваемый на развес, необходимо подвергать термической обработке.') WHERE id = '9afd3dbd-2a81-4f82-b4a6-f0c365cace3a';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Фейхоа'), description_ru = COALESCE(description_ru, 'Богат йодом и полезен для щитовидной железы.') WHERE id = '9ff783a8-6911-4a46-97cd-a4a18396bb13';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Шитьё'), description_ru = COALESCE(description_ru, 'Безопасно, но не сидите долго в одном положении.') WHERE id = 'a07b8699-6338-4bca-94a8-92fcb9ae10db';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Мушмула'), description_ru = COALESCE(description_ru, 'Безопасна.') WHERE id = 'a1f606c2-1658-4e47-bfea-06a80cc7dce7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Лазерная эпиляция'), description_ru = COALESCE(description_ru, 'Лазерный луч не проникает глубоко, однако боль может вызвать тонус матки. Врачи обычно рекомендуют отложить процедуру.') WHERE id = 'a4a9d193-8a0c-48ee-9372-9b37e5b999aa';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Тархун'), description_ru = COALESCE(description_ru, 'Безопасен в пищевых количествах.') WHERE id = 'a533b46d-afd9-4184-ad2d-ec9d133701ff';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Соль'), description_ru = COALESCE(description_ru, 'Употреблять можно, но избыток соли вызывает отёки. Её количество следует ограничить.') WHERE id = 'a5dd803c-a1ab-47f5-acc3-d5aefdbeca54';
