UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Варенье из инжира'), description_ru = COALESCE(description_ru, 'Полезно для пищеварения.') WHERE id = 'b62f0f82-1af4-4811-910c-583d477987e7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Булгур'), description_ru = COALESCE(description_ru, 'Содержит больше клетчатки, чем рис, и полезен для здоровья.') WHERE id = 'b728c753-908a-4c9b-be3a-95f134405968';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Чай из листьев малины'), description_ru = COALESCE(description_ru, 'Разрешён только в конце 3-го триместра (36+ недель) для подготовки к родам.') WHERE id = 'b73d6256-1d85-4003-b933-0538a317f86f';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Лёгкие физические нагрузки'), description_ru = COALESCE(description_ru, 'Полезны пешие прогулки, плавание и йога для беременных.') WHERE id = 'b7a6fc30-872d-4080-ab2a-e4fa0f992f45';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Сахар / Сладости'), description_ru = COALESCE(description_ru, 'При наличии риска гестационного диабета необходимо строго контролировать потребление.') WHERE id = 'b89c53eb-32bc-412b-9682-ea88d2687297';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Езда на самокате'), description_ru = COALESCE(description_ru, 'Езда на самокате сопряжена с риском падения и травм, что может быть опасно во время беременности. Лучше всего отказаться от этого занятия.') WHERE id = 'c12e6733-ed2c-48df-9554-d169b3d3df30';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Ламинирование ресниц'), description_ru = COALESCE(description_ru, 'Химические вещества могут попасть в глаза, поэтому обязательно проведите тест на аллергию.') WHERE id = 'c1ad91ac-a9d7-4f8b-be51-bcfc572993be';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Какао'), description_ru = COALESCE(description_ru, 'Можно в небольших количествах. Содержит кофеин.') WHERE id = 'c2eda676-4afc-47fd-8f07-97d50bd55942';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Желе'), description_ru = COALESCE(description_ru, 'Желатин безопасен.') WHERE id = 'c3158731-b3af-4f97-ae42-ad2765f8836f';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кальян'), description_ru = COALESCE(description_ru, 'Содержит больше угарного газа и токсинов, чем сигареты.') WHERE id = 'c441fedf-30cd-4df7-aeb7-6c6d4c83ce37';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Дюшбара'), description_ru = COALESCE(description_ru, 'Безопасна, но будьте осторожны с перцем (может вызвать изжогу).') WHERE id = 'c61ac58a-22c8-4dd1-80b5-b2984f6468bc';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Авокадо'), description_ru = COALESCE(description_ru, 'Богат фолиевой кислотой и очень полезен.') WHERE id = 'c92870c6-4067-413f-bf1f-9c3c54c225ff';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Чёрный чай'), description_ru = COALESCE(description_ru, 'Содержит кофеин, поэтому не рекомендуется пить более 3-4 чашек в день. Не пейте одновременно с приёмом препаратов железа.') WHERE id = 'ca2a1163-b2b3-49fd-96d1-10ea4d670bb2';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Алкоголь'), description_ru = COALESCE(description_ru, 'Полностью запрещён. Напрямую вредит развитию плода.') WHERE id = 'cba6bf85-f14b-4324-9d48-90cac59a4bc7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Каштан'), description_ru = COALESCE(description_ru, 'Безопасен в приготовленном виде (в плове или запечённый в духовке).') WHERE id = 'cd2424c6-21a8-4752-9ae9-f4742dae93e4';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Рис / Гречка'), description_ru = COALESCE(description_ru, 'Это безопасные источники углеводов. Гречка является источником железа.') WHERE id = 'cd2c71df-2aa2-4603-8a8e-9819c6aaf1aa';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Сливочное масло'), description_ru = COALESCE(description_ru, 'Безопасно, является источником витаминов A и D.') WHERE id = 'cd79ac84-2fb6-4341-8c05-e49e124e966a';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Нут'), description_ru = COALESCE(description_ru, 'Является источником белка, но может вызвать вздутие живота и газообразование.') WHERE id = 'cdb23929-c1a6-4bcd-8e34-e26f78dde126';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Акварельные краски'), description_ru = COALESCE(description_ru, 'Безопасны, их можно использовать для хобби.') WHERE id = 'ce123d1a-41fc-4af9-8298-bf41eaa43197';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Айва'), description_ru = COALESCE(description_ru, 'Помогает при тошноте и улучшает пищеварение.') WHERE id = 'ce1b1478-cbd0-4b55-a0c0-52e6ae630be4';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Хиджама'), description_ru = COALESCE(description_ru, 'Существует риск кровопотери и инфекции. Может снизить артериальное давление.') WHERE id = 'ad945485-a623-4a91-afca-c9d7bba8b9c8';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Йогурт / Кефир'), description_ru = COALESCE(description_ru, 'Источник кальция и пробиотиков.') WHERE id = 'ada1521c-d651-4273-b3da-e1874aaf6625';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Авиаперелёт'), description_ru = COALESCE(description_ru, 'Перелёты коммерческими авиалиниями в целом считаются безопасными во время беременности. Однако перед полётом, особенно длительным, рекомендуется проконсультироваться с врачом, даже если беременность протекает без осложнений. Пейте больше воды, двигайтесь для профилактики образования тромбов и, если рекомендовано, используйте компрессионные чулки. Эти рекомендации также актуальны для кормящих мам, но во время длительных перелётов может потребоваться дополнительная подготовка для кормления и комфорта малыша.') WHERE id = 'b0855f6d-792e-4d72-a4d4-3509c5e9f5a1';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Лосось (Сёмга)'), description_ru = COALESCE(description_ru, 'Источник омега-3. Рекомендуется употреблять до 2 раз в неделю только в полностью приготовленном виде.') WHERE id = 'b0c7bfda-4110-4f88-8a68-a6303d1447c6';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Летать на самолёте'), description_ru = COALESCE(description_ru, 'Коммерческие авиаперелёты в целом считаются безопасными во время беременности. Рекомендуется проконсультироваться с врачом по поводу перелёта, особенно в третьем триместре, пить больше воды и регулярно двигаться для профилактики образования тромбов. Эти рекомендации также актуальны для кормящих мам, однако во время длительных перелётов необходимо дополнительно подготовиться, чтобы обеспечить кормление и комфорт малыша.') WHERE id = 'b1a7ab3d-fa21-4a98-ae31-159ea5e65822';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Суджук'), description_ru = COALESCE(description_ru, 'При умеренном употреблении суджук обычно безопасен во время грудного вскармливания, однако важно учитывать высокое содержание натрия и жира. Кроме того, острая пища иногда может влиять на малыша через грудное молоко, вызывая беспокойство или проблемы с пищеварением. Наблюдайте за реакцией малыша.') WHERE id = 'b4267eb3-6e6a-46f3-93ce-1dab05fea063';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Шоколад'), description_ru = COALESCE(description_ru, 'Можно употреблять в небольшом количестве, учитывая содержание кофеина и сахара.') WHERE id = 'b4392c92-b356-4f01-8438-8c0f357714ef';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Кальций'), description_ru = COALESCE(description_ru, 'Важен для костей и зубов.') WHERE id = 'b45209df-c697-4659-83df-1930e5ece743';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Слива'), description_ru = COALESCE(description_ru, 'Безопасна и способствует пищеварению.') WHERE id = 'b48ef54c-3301-4c72-9e1d-015b47bf0be0';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Консервированный тунец'), description_ru = COALESCE(description_ru, 'Разрешается употреблять не более 140 граммов в неделю из-за риска содержания ртути.') WHERE id = 'b5136762-1228-4319-a02d-71a442045140';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Бандаж (пояс)'), description_ru = COALESCE(description_ru, 'Уменьшает боль в пояснице. Носите по рекомендации врача.') WHERE id = 'ce5d270b-9ea1-4416-b1ff-dde38b8ca2f7';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Варенье из грецких орехов'), description_ru = COALESCE(description_ru, 'Богато йодом, но содержит много сахара.') WHERE id = 'cf62fa05-9fb2-434a-a4ab-259a3cf6c357';
UPDATE public.safety_items SET name_ru = COALESCE(name_ru, 'Омега-3'), description_ru = COALESCE(description_ru, 'Важна для развития мозга.') WHERE id = 'd038498a-680b-480c-b90b-e0469a383504';
