UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Врач-специалист Лейла Ибрагимли'), specialty_ru = COALESCE(specialty_ru, 'Акушер-гинеколог'), description_ru = COALESCE(description_ru, 'Опыт: 16 лет
Языки: немецкий, английский, русский, турецкий
Образование: Азербайджанский государственный медицинский университет
Области интересов: беременность, ведение беременности, бесплодие, лечение бесплодия, искусственное оплодотворение
Услуги: гистероскопия, лапароскопия, открытые операции

После успешного окончания Азербайджанского медицинского университета с отличием врач-специалист Лейла Ибрагимли продолжила образование в рамках программы Министерства образования Азербайджана «Обучение за рубежом», став стипендиатом Министерства образования и Германской службы академических обменов (DAAD) в Германии. Успешно сдав экзамен по специальности во Франкфурте (Германия), Лейла Ибрагимли работала в таких авторитетных медицинских учреждениях, как Клинический медицинский центр № 1, клиника Ашаффенбурга (Германия), Университетская клиника Мангейма (Германия) и клиника IVF-Spain в Аликанте (Испания).'), address_ru = COALESCE(address_ru, 'Baku Medical Plaza / Medilux, AZ1069, ул. Короля Гусейна, 66B, Наримановский р-н, Баку, Азербайджан') WHERE id = 'c67c297b-8171-4b17-a6b4-b2ef5d740a7c';
UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Врач-специалист Гюльтап Халыглы'), specialty_ru = COALESCE(specialty_ru, 'Акушер-гинеколог'), description_ru = COALESCE(description_ru, 'Опыт: 11 лет
Языки: английский, турецкий
Образование: Азербайджанский государственный медицинский университет
Магистратура: Медицинский факультет Эгейского университета
Области интересов: роды, ведение беременности, кесарево сечение, лечение бесплодия, искусственное оплодотворение
Услуги: ведение беременности и роды, кесарево сечение, естественные роды, лечение бесплодия, искусственное оплодотворение, ведение патологий беременности и беременности высокого риска, гинекологические операции (открытые и лапароскопические), онкогинекология, проблемы недержания мочи, эстетическая гинекология

Гюльтап Халыглы родилась в 1992 году в Баку. В 1999 году поступила в 1-й класс бакинской школы № 246. В 2006 году продолжила обучение в лицее с химико-биологическим уклоном и окончила его в 2010 году. В 2010–2016 годах училась на лечебном факультете Азербайджанского медицинского университета. В настоящее время замужем.'), address_ru = COALESCE(address_ru, 'Ege Hospital, ул. Гасана Алиева, 38') WHERE id = 'ede37d99-611e-4797-b952-e25f1c504f40';
UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Caspian International Hospital'), specialty_ru = COALESCE(specialty_ru, 'Акушерство и неонатология'), description_ru = COALESCE(description_ru, 'Роды, неонатология, поликлиника. Стратегически важный для района Бадамдар родильный дом со спокойной обстановкой. Работает с 2013 года.'), address_ru = COALESCE(address_ru, 'пос. Бадамдар, 1-й жилой массив, 31') WHERE id = 'ee4bb260-28ea-42b3-8295-b048148e0380';
UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Д-р Медина Дильбази'), specialty_ru = COALESCE(specialty_ru, 'Эндокринолог'), description_ru = COALESCE(description_ru, 'Опыт: 16 лет
Языки: азербайджанский
Образование: Азербайджанский государственный медицинский университет
Сферы интересов: дислипидемии (нарушения содержания жиров в крови), избыточный вес и ожирение, метаболический синдром, ожирение, сахарный диабет 1-го и 2-го типа, аспирационная биопсия щитовидной железы, заболевания надпочечников, заболевания половых желез и эндокринное бесплодие (СПКЯ, ВГКН, ВГД), заболевания гипофиза, остеопороз и нарушения метаболизма костной ткани

Д-р Медина Дильбази — специалист с более чем 15-летним клиническим опытом в области эндокринологии и диетологии. В настоящее время работает эндокринологом-диетологом в Leyla Medical Center, занимаясь диагностикой, лечением и длительным наблюдением заболеваний гормональной системы. В 2004–2010 годах училась на лечебном факультете Азербайджанского медицинского университета, а в 2011 году завершила интернатуру по эндокринологии в Городской клинической больнице № 4. Затем проходила курсы повышения квалификации по эндокринологии и метаболизму в Эгейском университете в Турции, совершенствуя знания и навыки в области диабета, заболеваний щитовидной железы, диетологии, остеопороза и метаболических заболеваний. В течение профессиональной деятельности участвовала в конференциях Турецкого общества эндокринологии и метаболизма (TEMD), научных мероприятиях по бариатрической и метаболической хирургии, а также в международных конгрессах по эндокринологии и ожирению. Применяя современные протоколы диагностики и лечения в повседневной клинической практике, составляет индивидуальный план лечения для каждого пациента. Д-р Медина Дильбази специализируется на комплексном ведении пациентов с ожирением, сахарным диабетом и заболеваниями щитовидной железы. Благодаря ориентированному на пациента подходу, научно обоснованным принципам лечения и непрерывному профессиональному развитию продолжает работать как один из признанных специалистов в области эндокринологии.'), address_ru = COALESCE(address_ru, 'Leyla Medical Center, ул. Ю. Сафароглу, 19ул. Ю. Сафароглу, 19') WHERE id = '0316cec0-4286-47d9-a7ed-c1d2468cf313';
UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Д-р Айнура Ибрагимова'), specialty_ru = COALESCE(specialty_ru, 'Детская неврология'), description_ru = COALESCE(description_ru, 'Опыт: 27 лет
Языки: азербайджанский
Образование: Азербайджанский государственный медицинский университет
Магистратура: Азербайджанский государственный медицинский университет
Сферы интересов: заикание у детей и подростков в возрасте 0-18 лет

Д-р Айнура Ибрагимова получила высшее медицинское образование в Азербайджанском медицинском университете в 1993–1999 годах. В 1999–2000 годах прошла интернатуру по неврологии в Азербайджанском медицинском университете и начала профессиональную деятельность как врач-невролог. В 2000–2003 годах работала неврологом в Загатальской центральной районной больнице. В 2004–2021 годах работала в лечебно-диагностическом центре «Шафа», где приобрела обширный опыт диагностики и лечения неврологических заболеваний. Уделяя большое внимание профессиональному развитию, специалист участвовала в программах повышения квалификации в ведущих университетах и медицинских учреждениях Турции. Работала врачом-наблюдателем на кафедре неврологии, а также в поликлинике ЭЭГ и неврологии Университета Башкент в Анкаре. Кроме того, проходила практику в качестве наблюдателя в поликлинике ЭМГ (электромиографии) кафедры неврологии Университета Мармара в Стамбуле. В октябре-ноябре 2017 года участвовала в работе нейрофизиологической поликлиники Университета Гази в Анкаре в качестве врача-наблюдателя, совершенствуя знания и навыки в области нейрофизиологической диагностики. В настоящее время работает в области детской неврологии, занимается диагностикой, лечением и длительным наблюдением заболеваний нервной системы у детей. Постоянно следит за научными достижениями и современными методами лечения, предоставляя пациентам медицинскую помощь на основе индивидуального подхода.'), address_ru = COALESCE(address_ru, 'Медицинский центр Сабунчу — отделение терапевтической поликлиники, City Clinic Hospital №3, Баку, Азербайджан') WHERE id = '211a59f8-e8a8-447c-94f9-806f7c02a5d8';
UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Liv Bona Dea Hospital'), specialty_ru = COALESCE(specialty_ru, 'Многопрофильная клиника'), description_ru = COALESCE(description_ru, 'Международные стандарты JCI, роботизированная хирургия, ведение беременности высокого риска, реанимация новорождённых. Комплекс площадью 37,500 кв.м, 137 коек, 9 VIP-палат, 28 реанимационных коек, 10 операционных. Партнёр турецкой сети "Liv Hospital".'), address_ru = COALESCE(address_ru, 'Низаминский р-н, ул. Мехди Аббасова, 2') WHERE id = '2275880d-85a5-4f4c-a70b-e575bc74d0f3';
UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Baku Medical Plaza (Бабек)'), specialty_ru = COALESCE(specialty_ru, 'ЭКО и акушерство'), description_ru = COALESCE(description_ru, 'ЭКО (искусственное оплодотворение), роды высокого риска, неонатология, крупный хирургический блок. Один из крупнейших в регионе центров родовспоможения и ЭКО. Технологии Tandem Cycle, Micro-TESE, PRP, Sperm Freezing.'), address_ru = COALESCE(address_ru, 'Хатаинский р-н, пр. Бабека, 92N') WHERE id = '444088a8-4836-4636-af8b-ff5bfdca71ec';
UPDATE public.healthcare_providers SET name_ru = COALESCE(name_ru, 'Д-р Рахшанда Алиева'), specialty_ru = COALESCE(specialty_ru, 'Акушер-гинеколог'), description_ru = COALESCE(description_ru, 'Опыт: 12 лет
Языки: азербайджанский, английский, русский, турецкий, немецкий
Образование: Азербайджанский государственный медицинский университет
Магистратура: Азербайджанский государственный медицинский университет
Сферы интересов: ведение беременности высокого риска, естественные роды, роды с эпидуральной анестезией, кесарево сечение, гинекологические заболевания и бесплодие, кисты яичников, эндометриоз, миома матки при беременности, миома матки, полипы матки, нарушения менструации, эндокринные нарушения, гормональные нарушения, болезненная менструация (дисменорея), аномальные маточные кровотечения, синдром поликистозных яичников, ранняя менопауза, менопауза, лапароскопическая хирургия, гистероскопические операции
Услуги: лапароскопическое лечение образований придатков матки и внематочной беременности, TVT / TOT, реконструкция тазового дна, кольпоклейзис, кольпопексия, лапароскопическое лечение недержания мочи, лапароскопическое лечение пролапса органов малого таза, лапароскопическая пектопексия, лапароскопическая сакрокольпопексия, создание неовлагалища (с лапароскопической поддержкой), органосохраняющая хирургия в клинически подходящих случаях, супрацервикальная лапароскопическая гистерэктомия, диссекция тазовых лимфатических узлов, адгезиолизис повышенной сложности, лапароскопическая склеротерапия эндометриомы, лапароскопическая цистэктомия яичника, органосохраняющие операции на яичниках, нервосберегающая хирургия эндометриоза, лечение глубокого инфильтративного эндометриоза повышенной сложности, сохраняющая фертильность лапароскопическая миомэктомия (включая множественные и крупные миомы), тотальная лапароскопическая гистерэктомия (TLH)

Д-р Рахшанда Алиева — акушер-гинеколог, специализирующийся на малоинвазивной гинекологической хирургии. Обладает обширным клиническим опытом в области сохранения женского здоровья, диагностики и лечения гинекологических заболеваний, наблюдения беременности и хирургических вмешательств. Д-р Рахшанда Алиева имеет международные сертификаты в области малоинвазивной гинекологической хирургии. Европейское общество гинекологической эндоскопии (ESGE) присвоило ей диплом бакалавра эндоскопии (уровень I) и диплом по малоинвазивной гинекологической хирургии (уровень II). Она также прошла практическое обучение малоинвазивной гинекологической хирургии в клинике Bethesda Agaplesion в Вуппертале, Германия, и участвовала в проведении лапароскопических и гистероскопических операций. За время профессиональной деятельности добилась успешных результатов в наблюдении беременности, проведении естественных родов и родов с эпидуральной анестезией, кесарева сечения, лапароскопических и гистероскопических вмешательств, вагинальной хирургии, эстетических процедур в интимной зоне и охране женского репродуктивного здоровья. КЛИНИЧЕСКАЯ ЭКСПЕРТИЗА: ЛАПАРОСКОПИЧЕСКАЯ ХИРУРГИЯ ПОВЫШЕННОЙ СЛОЖНОСТИ * Тотальная лапароскопическая гистерэктомия (TLH) * Супрацервикальная лапароскопическая гистерэктомия * Сохраняющая фертильность лапароскопическая миомэктомия (включая множественные и крупные миомы) * Лечение глубокого инфильтративного эндометриоза повышенной сложности * Нервосберегающая хирургия эндометриоза * Органосохраняющие операции на яичниках * Лапароскопическая цистэктомия яичника * Лапароскопическая склеротерапия эндометриом яичников * Адгезиолизис повышенной сложности * Лапароскопическая диссекция тазовых лимфатических узлов * Лапароскопическое лечение образований придатков матки и внематочной беременности * Органосохраняющая хирургия во всех клинически подходящих случаях * Создание неовлагалища (с лапароскопической поддержкой) ХИРУРГИЯ ТАЗОВОГО ДНА И УРОГИНЕКОЛОГИЯ * Лапароскопическая сакрокольпопексия * Лапароскопическая пектопексия * Лапароскопическое лечение пролапса органов малого таза * Лапароскопические операции по фиксации матки * Лапароскопическое лечение недержания мочи * Кольпопексия * Кольпоклейзис * Реконструкция тазового дна * TVT / TOT ГИСТЕРОСКОПИЧЕСКАЯ ХИРУРГИЯ ПОВЫШЕННОЙ СЛОЖНОСТИ * Офисная гистероскопия * Диагностическая гистероскопия * Оперативная гистероскопия * Гистероскопическая миомэктомия * Полипэктомия эндометрия * Резекция перегородки * Коррекция дисморфичной матки * Лечение редких мюллеровых аномалий * Гистероскопическое лечение беременности в рубце после кесарева сечения * Коррекция истмоцеле * Внутриматочный адгезиолизис (синдром Ашермана) * Гистероскопия у пациенток, не живущих половой жизнью АКУШЕРСТВО * Комплексное дородовое наблюдение * Ведение беременности высокого риска * Мягкое кесарево сечение (семейно-ориентированное кесарево сечение) * Вагинальные роды * Роды с эпидуральной анестезией * Оперативное акушерство ФЕТАЛЬНАЯ МЕДИЦИНА И ВНУТРИУТРОБНАЯ ТЕРАПИЯ * Детальное пренатальное УЗИ * Амниоцентез * Биопсия ворсин хориона (CVS) * Кордоцентез * Внутриутробное переливание крови * Вмешательства на плоде * Лечение TRAP-последовательности * Пренатальная диагностика и консультирование ⸻ ЭСТЕТИЧЕСКАЯ ГИНЕКОЛОГИЧЕСКАЯ ХИРУРГИЯ * Лабиопластика * Коррекция капюшона клитора * Перинеопластика * Увеличение больших половых губ (липофилинг и филлеры) * Функциональная и эстетическая вульвовагинальная реконструкция ВАГИНАЛЬНАЯ ХИРУРГИЯ * Тотальная вагинальная гистерэктомия * Передняя и задняя кольпорафия * Кольпопексия * Кольпоклейзис * Реконструкция тазового дна * TVT / TOT ЗДОРОВЬЕ ШЕЙКИ МАТКИ И ПРОФИЛАКТИЧЕСКАЯ ГИНЕКОЛОГИЯ * Кольпоскопия * Лечение дисплазии шейки матки * Профилактика ВПЧ * Скрининг рака шейки матки * Ежегодные профилактические гинекологические осмотры МЕНОПАУЗА И ЖЕНСКОЕ ЗДОРОВЬЕ * Ведение в период перименопаузы и менопаузы * Заместительная гормональная терапия * Наблюдение после менопаузы * Здоровье костной и сердечно-сосудистой систем * Ежегодный комплексный осмотр женского здоровья РАБОТА С ПРОФЕССИОНАЛЬНОЙ КОМАНДОЙ Все операции и роды проводятся в тесном сотрудничестве с опытной командой анестезиологов, неонатологов и других специалистов, чтобы обеспечить максимальную безопасность, оптимальные результаты и заботливое отношение к каждой пациентке. ⸻ ОБРАЗОВАНИЕ 2019 – настоящее время Соискатель степени PhD Кафедра акушерства и гинекологии Азербайджанский медицинский университет, Баку, Азербайджан 2011 – 2017 Резидентура по акушерству и гинекологии Азербайджанский медицинский университет, Баку, Азербайджан 2005 – 2011 Доктор медицины (MD) Азербайджанский медицинский университет, Баку, Азербайджан ⸻ МЕЖДУНАРОДНОЕ ОБУЧЕНИЕ 2017 – 2018 Клиническая специализация по малоинвазивной гинекологической хирургии Больница Bethesda Agaplesion, Вупперталь, Германия Фев – мар 2017 Клиническая специализация по пренатальному УЗИ Больница Университета Хаджеттепе, Анкара, Турция 2017 Обучение в Гисенской школе эндоскопической хирургии, Гисен, Германия 2015 – 2019 Участие в программах углублённого обучения лапароскопической и гистероскопической хирургии в Европе и Азии ⸻ МЕЖДУНАРОДНЫЕ СЕРТИФИКАТЫ ДИПЛОМ ESGE УРОВНЯ II ПО МАЛОИНВАЗИВНОЙ ГИНЕКОЛОГИЧЕСКОЙ ХИРУРГИИ Европейское общество гинекологической эндоскопии, Бельгия, декабрь 2017 ДИПЛОМ БАКАЛАВРА ESGE ПО ЭНДОСКОПИИ (УРОВЕНЬ I) Европейское общество гинекологической эндоскопии, Бельгия, август 2017 Курсы STORZ по лапароскопической и гистероскопической хирургии повышенной сложности Karl Storz, Тутлинген, Германия 2017–2018 В настоящее время д-р Рахшанда Алиева работает старшим ординатором отделения гинекологии DTX Hospital и оказывает пациенткам высококачественную медицинскую помощь на основе современных достижений медицины и индивидуального подхода.'), address_ru = COALESCE(address_ru, 'DTX Hospital, 8RQ3+H6X, ул. Нураддина Пашаева, Баку, Азербайджан') WHERE id = '4969e22f-dab6-4d36-a4b0-ddd79e526424';
